World master(){auto w=bmh::test::world12::complete_world();for(auto& [id,club]:w.clubs)for(size_t row=0;row<11;++row){auto& player=w.players.at(club.roster[row].player).attributes;player.w364=uint32_t(row%4);player.w368=uint32_t(club.country)<<27;}for(uint32_t i=0;i<54;++i){PlayerRecord p;p.id={1000000+i};p.attributes={"Source pool "+std::to_string(i),50u|(60u<<7)|(65u<<14),(i<50?5u:0u)<<27,i%4};w.players[p.id]=p;}for(uint32_t c=0;c<62;++c){ClubRecord club;club.id={3000000+c};club.country=Country(c);club.kind=ClubKind::national_team;club.name="Nation "+std::to_string(c);club.crest={club.id.value};w.crests[club.crest]={"W/TEST.VGA",0};w.clubs[club.id]=club;}w.validate();return w;}
GameState reference(){auto g=bmh::test::world12::national_reference();g.stocks.resize(12*0x5c);g.memory.add_block(layout::FundBlock,6*0x1c);g.memory.add_block(layout::EditorList,44*0x58);for(size_t n=0;n<4;++n)g.memory.set16(layout::EditorList+40*0x58+uint32_t(n*2),n?65535:0);g.manager_options[0]=1;g.memory.add_block(layout::Desktops,5*0x360);g.memory.add_block(layout::LeagueTableDisplayModes,8);g.memory.set16(layout::LeagueTableDisplayModes,0x11);g.memory.add_block(layout::ManagerSettings,8);g.memory.set16(layout::ManagerSettings,0x1ff);return g;}
